ALTER TABLE public.salons ADD COLUMN IF NOT EXISTS opening_time TEXT NOT NULL DEFAULT '09:00', ADD COLUMN IF NOT EXISTS closing_time TEXT NOT NULL DEFAULT '18:00'; COMMENT ON COLUMN public.salons.opening_time IS 'Horário de abertura do salão (HH:MM), configurado pelo dono'; COMMENT ON COLUMN public.salons.closing_time IS 'Horário de fechamento do salão (HH:MM), configurado pelo dono';